import assert from 'node:assert/strict';
if(process.env.ZEPTER_UI_FIXTURE!=='1')throw Error('Set ZEPTER_UI_FIXTURE=1 and start the isolated manager fixture.');
const base='http://127.0.0.1:4002/api';
const call=async(path,{method='GET',body,headers={}}={})=>{
 const response=await fetch(base+path,{method,headers:{'Content-Type':'application/json',...headers},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(10000)});
 return {status:response.status,data:await response.json()};
};
const auth=await call('/auth/refresh',{method:'POST'});
assert.equal(auth.data.accessToken,'isolated-ui-fixture');assert.equal(auth.data.user.role,'manager');
const id='555555555555555555555555';
const before=await call('/activities/'+id);assert.equal(before.status,200);
const version=before.data.activity.updatedAt;
const updated=await call('/activities/'+id,{method:'PATCH',headers:{'If-Match':`"${version}"`},body:{title:'UI talas 03 — upravljanje',description:'Priprema i provera mobilnog dizajna.',assigneeIds:['222222222222222222222222'],priority:'high',dueDate:'2026-11-30',status:'completed'}});
assert.equal(updated.status,200);assert.equal(updated.data.activity.progress,100);assert.equal(updated.data.projectProgress,100);
assert.equal(updated.data.activity.actualWork,before.data.activity.actualWork);
assert.equal((await call('/activities/'+id,{method:'PATCH',headers:{'If-Match':`"${version}"`},body:{title:'Must not overwrite'}})).status,409);
const ownVersion=updated.data.activity.updatedAt;
assert.equal((await call('/activities/'+id,{method:'PATCH',headers:{'If-Match':`"${ownVersion}"`},body:{dueDate:null}})).status,200);
console.log('OK manager metadata, assignment, status/progress, unchanged work, project progress, stale version and cleared deadline');
const history=await call('/activities/'+id+'/history?sectorId='+'f7'.repeat(12));
assert.equal(history.status,200);assert.equal(history.data.worklogs.items.length,1);
assert.equal(history.data.worklogs.items[0].done,'Pripremljen prvi predlog dizajna.');
assert.ok(history.data.events.items.some(item=>item.fields.includes('assigneeIds')));
assert.equal(JSON.stringify(history.data).includes('fixture-private-value'),false);
assert.equal((await call('/activities/'+'f3'.repeat(12)+'/history')).data.worklogs.items.length,0);
console.log('OK scoped history, existing daily work and safe audit projection');
const parent='a3'.repeat(12);
assert.equal((await call('/comments',{method:'POST',body:{targetType:'activity',targetId:id,parentId:parent,body:'Smernice su primljene. Pripremićemo pregled.',kind:'comment'}})).status,201);
const thread=await call('/comments?targetType=activity&targetId='+id);
assert.equal(thread.data.items.find(item=>item._id===parent).responseStatus,'answered');
console.log('OK contextual answer to president activity instruction');
const daily=await call('/reports?type=daily&limit=10'),weekly=await call('/reports?type=weekly&limit=10');
assert.equal(daily.status,200);assert.equal(daily.data.total,12);assert.equal(daily.data.items.length,10);
assert.ok(daily.data.items.every(item=>item.type==='daily'&&item.sector._id===auth.data.user.sector));
assert.ok(daily.data.items.some(item=>item.status==='draft'));assert.equal(weekly.data.total,1);
assert.equal((await call('/reports?type=daily&limit=10&page=2')).data.items.length,2);
assert.equal((await call('/reports?type=daily&sectorId='+'f7'.repeat(12))).data.total,12);
assert.equal((await call('/reports/'+'ab'.repeat(12))).status,403);
assert.equal((await call('/reports/'+daily.data.items[0]._id)).status,200);
const preview=await call('/reports/preview?'+new URLSearchParams({scope:'sector',id:auth.data.user.sector,type:'weekly',day:'2026-11-08'}));
assert.equal(preview.status,200);assert.equal(preview.data.report.periodStart,'2026-11-02');assert.equal(preview.data.report.periodEnd,'2026-11-08');
assert.ok(preview.data.report.completed.some(item=>item.text==='Pripremljen prvi predlog dizajna.'));
console.log('OK daily/weekly list, drafts/published status, pagination, sector isolation, saved detail and generated weekly preview');
console.log('All wave 03 API checks passed; no MongoDB connection.');
